class JobRunner {
    var title = "Data Job"
    var action: (() -> Void)?
    deinit { print("JobRunner deallocated") }
}

var runner: JobRunner? = JobRunner()
runner?.action = { [weak runner] in
    print("Running \(runner?.title ?? "none")")
}
runner?.action?()
runner = nil
print("After runner nil")

class LeakTester {
    var closure: (() -> Void)?
    func setup() {
        closure = {
            _ = self
        }
    }
    deinit { print("LeakTester freed") }
}

var tester: LeakTester? = LeakTester()
tester?.setup()
tester = nil
print("After tester nil")

class Printer {
    let text: String
    init(_ text: String) { self.text = text }
    func printAll() {
        [1, 2].forEach { _ in
            print(self.text)
        }
    }
    deinit { print("Printer deallocated") }
}

var p: Printer? = Printer("Hello")
p?.printAll()
p = nil
print("After printer nil")

