protocol EngineDelegate: AnyObject {
    func engineDidStart()
}

class Engine {
    weak var delegate: EngineDelegate?
    func ignite() {
        delegate?.engineDidStart()
    }
    deinit { print("Engine deallocated") }
}

class Car: EngineDelegate {
    let engine = Engine()
    init() { engine.delegate = self }
    func engineDidStart() { print("Vroom") }
    deinit { print("Car deallocated") }
}

var car: Car? = Car()
car?.engine.ignite()
car = nil
print("After car nil")

class SessionHandler {
    var callback: (() -> Void)?
    let token = "XYZ"
    func bind() {
        callback = { [weak self] in
            guard let self else {
                print("Self was nil")
                return
            }
            print("Token: \(self.token)")
        }
    }
    deinit { print("SessionHandler freed") }
}

var s: SessionHandler? = SessionHandler()
s?.bind()
let savedCallback = s?.callback
s = nil
savedCallback?()

