class DataLoader {
    let endpoint: String
    var onResult: (() -> Void)?
    init(endpoint: String) {
        self.endpoint = endpoint
    }
    func configure() {
        onResult = { [weak self] in
            guard let self else { return }
            print("Fetched \(self.endpoint)")
        }
    }
    deinit {
        print("DataLoader deallocated")
    }
}

var loader: DataLoader? = DataLoader(endpoint: "/items")
loader?.configure()
loader?.onResult?()
loader = nil
print("Finished loader test")

protocol FormDelegate: AnyObject {
    func formSubmitted()
}

class FormView {
    weak var delegate: FormDelegate?
    func submit() {
        delegate?.formSubmitted()
    }
}

class FormPresenter: FormDelegate {
    let form = FormView()
    init() {
        form.delegate = self
    }
    func formSubmitted() {
        print("Form processed")
    }
    deinit {
        print("Presenter deallocated")
    }
}

var presenter: FormPresenter? = FormPresenter()
presenter?.form.submit()
presenter = nil
print("Finished presenter test")

class TimerHelper {
    let id: Int
    var onTick: (() -> Void)?
    init(id: Int) {
        self.id = id
    }
    func setup() {
        onTick = { [weak self] in
            guard let self else { return }
            print("Tick: \(self.id)")
        }
    }
    func cleanUp() {
        onTick = nil
    }
    deinit {
        print("TimerHelper deallocated")
    }
}

var timer: TimerHelper? = TimerHelper(id: 1)
timer?.setup()
timer?.onTick?()
timer?.cleanUp()
timer = nil
print("Finished timer test")
